function bindFilters(){let form=$('#payableFilterForm');if(!form)return;form.onsubmit=e=>{e.preventDefault();let next={};for(let el of document.querySelectorAll('[data-payable-filter]'))next[el.dataset.payableFilter]=el.type==='checkbox'?el.checked:el.value.trim();for(let key of ['date','due','paidDate'])if(next[key+'From']&&next[key+'To']&&next[key+'From']>next[key+'To']){$('#payableFilterError').textContent='A data inicial precisa ser anterior à data final.';return}if(next.min&&next.max&&Number(next.min)>Number(next.max)){$('#payableFilterError').textContent='O saldo mínimo não pode superar o máximo.';return}filters=next;api.render()};$('#payableFilterClear').onclick=()=>{filters={};api.render()}}
